function initMagnet() {
var bar = $('magProviderBar');
if (bar) {
bar.addEventListener('click', function (e) {
var btn = e.target.closest('button[data-mag-provider]');
if (!btn) return;
magSetProvider(btn.getAttribute('data-mag-provider'));
magLoadDirs();
});
}
var pick115 = $('magDirPick');
if (pick115)
pick115.addEventListener('change', function () {
magPickChange(true);
});
var ref115 = $('magDirRefresh');
if (ref115) ref115.addEventListener('click', magLoadDirs);
var pickpp = $('magPpDirPick');
if (pickpp)
pickpp.addEventListener('change', function () {
magPickChange(false);
});
var refpp = $('magPpRefresh');
if (refpp) refpp.addEventListener('click', magLoadDirs);
var saveBtn = $('btnMagSave');
if (saveBtn) saveBtn.addEventListener('click', saveMagnet);
var clearBtn = $('btnMagClear');
if (clearBtn) clearBtn.addEventListener('click', magClear);
loadMagnet();
}
function initM3u8() {
var cleanToggle = $('globalM3u8CleanToggle');
if (cleanToggle) {
cleanToggle.addEventListener('change', function (e) {
onToggleChange('clean', e.target.checked, cleanToggle);
});
}
var accelToggle = $('globalM3u8AccelToggle');
if (accelToggle) {
accelToggle.addEventListener('change', function (e) {
onToggleChange('accel', e.target.checked, accelToggle);
});
}
var blSearch = $('m3u8BlacklistSearch');
if (blSearch) {
blSearch.addEventListener('input', renderBlacklistList);
}
var filterGroup = $('blFilterGroup');
if (filterGroup) {
filterGroup.addEventListener('click', function (e) {
var btn = e.target.closest('button[data-filter]');
if (!btn) return;
var mode = btn.getAttribute('data-filter');
if (mode === blFilterMode) return;
blFilterMode = mode;
updateBlacklistFilterButtons();
renderBlacklistList();
});
}
var blList = $('m3u8BlacklistList');
if (blList) {
blList.addEventListener('change', async function (e) {
var cb = e.target.closest('input[type="checkbox"][data-blkey]');
if (!cb) return;
var key = cb.getAttribute('data-blkey');
var checked = cb.checked;
if (checked) blacklistKeys.add(key);
else blacklistKeys.delete(key);
var itemEl = cb.closest('.pb-bl-item');
if (itemEl) itemEl.classList.toggle('is-checked', checked);
updateBlacklistCount();
updateBlacklistFilterButtons();
var ok = await saveBlacklist();
if (!ok) {
if (checked) blacklistKeys.delete(key);
else blacklistKeys.add(key);
cb.checked = !checked;
if (itemEl) itemEl.classList.toggle('is-checked', !checked);
updateBlacklistCount();
updateBlacklistFilterButtons();
} else if (!checked && blFilterMode === 'checked') {
renderBlacklistList();
}
});
}
var selectAllBtn = $('blSelectAllBtn');
if (selectAllBtn) {
selectAllBtn.addEventListener('click', async function () {
var inputs = document.querySelectorAll('#m3u8BlacklistList input[data-blkey]');
var added = 0;
inputs.forEach(function (inp) {
var key = inp.getAttribute('data-blkey');
if (!blacklistKeys.has(key)) {
blacklistKeys.add(key);
inp.checked = true;
var itemEl = inp.closest('.pb-bl-item');
if (itemEl) itemEl.classList.add('is-checked');
added++;
}
});
if (added > 0) {
updateBlacklistCount();
updateBlacklistFilterButtons();
var ok = await saveBlacklist();
if (ok) {
toast('\u5DF2\u5C07\u7576\u524D ' + added + ' \u500B\u7AD9\u9EDE\u52A0\u5165\u9ED1\u540D\u55AE', 'success');
}
} else {
toast('\u7576\u524D\u5217\u8868\u7684\u7AD9\u9EDE\u5DF2\u5168\u5728\u9ED1\u540D\u55AE\u4E2D', 'info');
}
});
}
var clearAllBtn = $('blClearAllBtn');
if (clearAllBtn) {
clearAllBtn.addEventListener('click', async function () {
if (!blacklistKeys.size) return;
var prevSize = blacklistKeys.size;
blacklistKeys.clear();
var inputs = document.querySelectorAll('#m3u8BlacklistList input[data-blkey]');
inputs.forEach(function (inp) {
inp.checked = false;
var itemEl = inp.closest('.pb-bl-item');
if (itemEl) itemEl.classList.remove('is-checked');
});
updateBlacklistCount();
updateBlacklistFilterButtons();
var ok = await saveBlacklist();
if (ok) {
toast('\u5DF2\u6E05\u7A7A\u7AD9\u9EDE\u9ED1\u540D\u55AE\uFF08\u5171\u79FB\u9664 ' + prevSize + ' \u500B\uFF09', 'success');
if (blFilterMode === 'checked') renderBlacklistList();
}
});
}
}
(function init() {
try {
if (window.CatPaw && CatPaw.theme && typeof CatPaw.theme.mountToggle === 'function') {
CatPaw.theme.mountToggle('#themeToggleBtn');
}
} catch (err) {}
var tab = 'pan';
try {
var t = new URL(window.location.href).searchParams.get('tab');
if (t === 'm3u8' || t === 'pan' || t === 'magnet') tab = t;
} catch (e) {}
$('tabBar').addEventListener('click', function (e) {
var btn = e.target.closest('button[data-tab]');
if (!btn) return;
switchTab(btn.getAttribute('data-tab'));
});
switchTab(tab);
requestAnimationFrame(function () {
updateIndicator();
});
window.addEventListener('resize', function () {
updateIndicator();
});
$('btnSaveApply').addEventListener('click', function () {
save(true);
});
$('btnSave').addEventListener('click', function () {
save(false);
});
$('btnApply').addEventListener('click', applyAll);
loadLoginProviders().then(function () {
load();
});
initPanToggle();
var fb = $('formBox');
if (fb) {
fb.addEventListener('blur', function (e) {
if (e.target && e.target.matches && e.target.matches('input[data-section]')) {
if (typeof e.target.value === 'string') {
e.target.value = e.target.value.trim();
}
}
}, true);
}
initLogin();
initM3u8();
initMagnet();
loadM3u8Settings();
fetchAllSources();
})();
